class KutuphaneServisi:
    def __init__(self):
        self.kitaplar = {}
        self.uyeler = {}
        self.kayitlar = []

    def kitap_ekle(self, kitap):
        self.kitaplar[kitap.id] = kitap

    def uye_ekle(self, uye):
        self.uyeler[uye.id] = uye

    def _aktif(self, kitap_id):
        return next((k for k in self.kayitlar if k.kitap_id == kitap_id and k.iade is None), None)

    def odunc_ver(self, kitap_id, uye_id, tarih):
        """Kitabı üyeye verir. Kitap/üye yoksa ya da kitap zaten ödünçteyse ValueError. Ayrıca kitap sınırı kontrol edilir."""
        if kitap_id not in self.kitaplar or uye_id not in self.uyeler:
            raise ValueError("kitap ya da üye bulunamadı")
        if self._aktif(kitap_id):
            raise ValueError("kitap zaten ödünçte")

        uye = self.uyeler[uye_id]
        aktif_kitaplar_sayisi = len([k for k in self.kayitlar if k.uye_id == uye_id and k.iade is None])

        sinir = 5 if uye.tur == "ogrenci" else 3
        if aktif_kitaplar_sayisi >= sinir:
            raise ValueError("kitap sınırı aşıldı")

        kayit = Odunc(kitap_id, uye_id, tarih)
        self.kayitlar.append(kayit)
        return kayit

    def iade_al(self, kitap_id, tarih):
        """Kitabın iadesini alır, cezayı hesaplar ve ödünç kaydını döndürür."""
        kayit = self._aktif(kitap_id)
        if kayit is None:
            raise ValueError("kitap ödünçte değil")

        kayit.iade = tarih
        self._hesapla_ceza(kayit)
        return kayit

    def _hesapla_ceza(self, kayit):
        uye = self.uyeler[kayit.uye_id]
        gun_sayisi = (kayit.iade - kayit.alinma).days
        gecikme_gunu = max(0, gun_sayisi - 14)

        if gecikme_gunu <= 0:
            kayit.ceza = 0.0
            return

        ceza_miktari = 0.0
        # İlk 7 gün için 2.50 TL, sonraki günler için 5.00 TL
        if gecikme_gunu <= 7:
            ceza_miktari = gecikme_gunu * 2.50
        else:
            ceza_miktari = (7 * 2.50) + ((gecikme_gunu - 7) * 5.00)

        # Üst sınır 150 TL
        ceza_miktari = min(ceza_miktari, 150.0)

        # Öğrenci indirimi
        if uye.tur == "ogrenci":
            ceza_miktari = ceza_miktari * 0.5

        kayit.ceza = round(ceza_miktari, 2)

    def toplam_ceza(self, uye_id):
        """Üyenin iade edilmiş tüm cezalarının toplamı."""
        return round(sum(k.ceza for k in self.kayitlar if k.uye_id == uye_id and k.iade is not None), 2)

    def oduncteki_kitaplar(self, uye_id):
        return sorted(k.kitap_id for k in self.kayitlar if k.uye_id == uye_id and k.iade is None)

